def look_and_say_sequence(start: str, n: int) -> str:
    if n <= 0:
        raise ValueError("n must be a positive integer")

    current = start
    if n == 1:
        return current

    for _ in range(1, n):
        next_seq = []
        i = 0
        while i < len(current):
            count = 1
            while i + 1 < len(current) and current[i] == current[i + 1]:
                count += 1
                i += 1
            next_seq.append(str(count))
            next_seq.append(current[i])
            i += 1
        current = "".join(next_seq)

    return current
